check.mcp_script:
#!/bin/sh
while IFS= read -r line; do
  case "$line" in
    *'"method":"tools/list"'*) printf '%s\n' '{"jsonrpc":"2.0","id":1,"result":{"resultType":"complete","tools":[{"name":"answer","description":"Answer from fixture","inputSchema":{"type":"object","properties":{"question":{"type":"string"}}}}]}}' ;;
    *'"method":"tools/call"'*) printf '%s\n' '{"jsonrpc":"2.0","id":2,"result":{"resultType":"complete","content":[{"type":"text","text":"mcp-configured-result"},{"type":"image","mimeType":"image/gif","data":"R0lGODlhTUFSTElO"}]}}' ;;
  esac
done
